from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Literal

@dataclass(frozen=True)
class WhereClause:
    """A WHERE clause with column, operator, and comparison value."""
    column: str
    op: Literal["=", "!=", ">", "<", ">=", "<="]
    value: str | float

@dataclass(frozen=True)
class OrderBy:
    """An ORDER BY clause with column and sort direction."""
    column: str
    direction: Literal["ASC", "DESC"]

@dataclass(frozen=True)
class Query:
    """Parsed SQL-like query with columns, optional WHERE/ORDER BY/LIMIT."""
    columns: list[str] | Literal["*"]
    where: WhereClause | None = None
    order_by: OrderBy | None = None
    limit: int | None = None

# ---------------------------------------------------------------------------
# Tokenizer
# ---------------------------------------------------------------------------

_TOKEN_RE = re.compile(
    r"""
        (?P<quoted_single>'(?:''|[^'])*')
      | (?P<quoted_double>"(?:""|[^"])*")
      | (?P<comma>,)
      | (?P<word>[^\s,]+)
    """,
    re.VERBOSE,
)

def _tokenize(sql: str) -> list[str]:
    """Split *sql* into whitespace-separated tokens, keeping quoted strings intact."""
    tokens: list[str] = []
    for m in _TOKEN_RE.finditer(sql):
        raw = m.group()
        if m.lastgroup == "quoted_single":
            # Strip outer quotes and unescape '' -> '
            raw = raw[1:-1].replace("''", "'")
        elif m.lastgroup == "quoted_double":
            raw = raw[1:-1].replace('""', '"')
        tokens.append(raw)
    return tokens

# ---------------------------------------------------------------------------
# Parser helpers
# ---------------------------------------------------------------------------

_OPERATORS = {"=", "!=", ">", "<", ">=", "<="}


class _Parser:
    def __init__(self, tokens: list[str]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> str | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self) -> str:
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect_keyword(self, keyword: str) -> None:
        """Consume a case-insensitive keyword token."""
        tok = self.peek()
        if tok is None or tok.upper() != keyword:
            raise ValueError(f"expected '{keyword}', got {tok!r}")
        self.consume()

    def at_end(self) -> bool:
        return self.pos >= len(self.tokens)

# ---------------------------------------------------------------------------
# parse_query
# ---------------------------------------------------------------------------

def parse_query(sql: str) -> Query:
    """Tokenize and recursively-descent-parse a SQL-like query string into a Query AST."""
    tokens = _tokenize(sql)
    if not tokens:
        raise ValueError("empty query")

    p = _Parser(tokens)

    # SELECT
    p.expect_keyword("SELECT")

    # Columns: '*' or comma-separated identifiers
    first_col = p.peek()
    if first_col is None:
        raise ValueError("missing columns after SELECT")
    first_col = p.consume()
    if first_col.upper() == "*":
        columns: list[str] | Literal["*"] = "*"
    else:
        columns: list[str] | Literal["*"] = [first_col]
        while p.peek() == ",":
            p.consume()  # comma
            next_col = p.peek()
            if next_col is None:
                raise ValueError("missing column after comma")
            columns.append(p.consume())

    # WHERE (optional)
    where: WhereClause | None = None
    if p.peek() and p.peek().upper() == "WHERE":
        p.consume()  # WHERE
        col = p.consume()
        op_tok = p.consume()
        if op_tok not in _OPERATORS:
            raise ValueError(f"invalid operator {op_tok!r}")
        val_raw = p.consume()
        # Try numeric parse
        try:
            value: str | float = float(val_raw)
        except ValueError:
            value = val_raw
        where = WhereClause(column=col, op=op_tok, value=value)

    # ORDER BY (optional)
    order_by: OrderBy | None = None
    if p.peek() and p.peek().upper() == "ORDER":
        p.consume()  # ORDER
        p.expect_keyword("BY")
        col = p.consume()
        direction: Literal["ASC", "DESC"] = "ASC"
        if p.peek() and p.peek().upper() in ("ASC", "DESC"):
            direction = p.consume().upper()  # type: ignore[assignment]
        order_by = OrderBy(column=col, direction=direction)

    # LIMIT (optional)
    limit: int | None = None
    if p.peek() and p.peek().upper() == "LIMIT":
        p.consume()  # LIMIT
        lim_raw = p.consume()
        try:
            limit = int(lim_raw)
        except ValueError:
            raise ValueError(f"LIMIT must be an integer, got {lim_raw!r}")

    if p.at_end():
        return Query(columns=columns, where=where, order_by=order_by, limit=limit)
    raise ValueError(f"unexpected token {p.peek()!r}")

# ---------------------------------------------------------------------------
# _compare
# ---------------------------------------------------------------------------

def _compare(cell: str, op: str, value: str | float) -> bool:
    """Compare a cell against a value using numeric dispatch when value is a number."""
    if isinstance(value, float):
        try:
            cell_num = float(cell)
        except ValueError:
            raise ValueError("cannot compare string to number")
        if op == "=":
            return cell_num == value
        if op == "!=":
            return cell_num != value
        if op == ">":
            return cell_num > value
        if op == "<":
            return cell_num < value
        if op == ">=":
            return cell_num >= value
        if op == "<=":
            return cell_num <= value
    # String comparison
    if op == "=":
        return cell == value
    if op == "!=":
        return cell != value
    if op == ">":
        return cell > value
    if op == "<":
        return cell < value
    if op == ">=":
        return cell >= value
    if op == "<=":
        return cell <= value
    raise ValueError(f"unknown operator {op!r}")

# ---------------------------------------------------------------------------
# evaluate
# ---------------------------------------------------------------------------

def evaluate(query: Query, rows: list[dict[str, str]]) -> list[dict[str, str]]:
    """Apply filter → sort → project → limit pipeline to rows per the Query AST."""
    result = list(rows)

    # 1. Filter
    if query.where is not None:
        w = query.where
        result = [r for r in result if _compare(r[w.column], w.op, w.value)]

    # 2. Sort
    if query.order_by is not None:
        ob = query.order_by
        # Determine sort key: try numeric first, fall back to lexicographic
        def _sort_key(row: dict[str, str]) -> tuple[int, float | str]:
            try:
                return (0.0, float(row[ob.column]))
            except (ValueError, KeyError):
                return (1.0, row[ob.column])

        # Check if ALL rows have numeric values for this column
        all_numeric = True
        for r in result:
            try:
                float(r[ob.column])
            except (ValueError, KeyError):
                all_numeric = False
                break

        if all_numeric:
            result.sort(key=lambda r: float(r[ob.column]), reverse=(ob.direction == "DESC"))
        else:
            result.sort(key=lambda r: r[ob.column], reverse=(ob.direction == "DESC"))

    # 3. Project columns
    if query.columns != "*":
        cols = list(query.columns)
        result = [{c: r[c] for c in cols} for r in result]

    # 4. Limit
    if query.limit is not None:
        result = result[:query.limit]

    return result

